def parse(signal_flow_str: str) -> SignalFlowProgram:
    """
    Parses a SignalFlow string, creating a SignalFlowProgram.

    Args:
        signal_flow_str: A SignalFlow program as a string

    Returns:
        A SignalFlowProgram object
    """
    program = SignalFlowProgram()

    if signal_flow_str:
        functions = []
        for line in signal_flow_str.split('\n'):
            func = parse_function(line)
            if func:
                functions.append(func)

        if functions:
            program.add_functions(functions)

    return program


def parse_function(func_string: str) -> Union[Any, None]:
    """
    Parses a SignalFlow function string and returns a function object.

    Args:
        func_string: A SignalFlow function string

    Returns:
        A SignalFlow function object or None
    """
    func_string = func_string.strip()
    if not func_string or func_string.startswith('#'):
        return None

    signal_flow_function_regex = r'^(?:([a-zA-Z_$][0-9a-zA-Z_$]*)\s*=\s*)?(data|filter)\((.*?)\)(?=\s*(?:\.|$))'
    match = re.match(signal_flow_function_regex, func_string)

    if match:
        variable_name = match.group(1)
        function_name = match.group(2)
        params_string = match.group(3).strip()
        params = parse_param_string(params_string)

        if function_name == 'data':
            func = parse_data_function(params)
            if variable_name:
                func.label = variable_name

            method_regex = r'\.([a-zA-Z_$][0-9a-zA-Z_$]*)\(([^)]*)\)'
            method_matches = re.finditer(method_regex, func_string)

            for method_match in method_matches:
                method_name = method_match.group(1)
                method_params = parse_param_string(method_match.group(2))
                func.method(method_name, method_params if method_params else None)

            return func
        elif function_name == 'filter':
            filter_function = parse_filter_function(func_string)

            if variable_name:
                filter_function.label = variable_name

            return filter_function

    return GenericFunction(func_string)


def parse_data_function(params: List[str]) -> Any:
    """
    Parses parameters for a data function.

    Args:
        params: List of parameter strings

    Returns:
        A Data object
    """
    data_obj = data({'metric': params[0] if params else ''})

    for param in params[1:]:
        filters = parse_filters(param)
        if filters:
            data_obj.filters(filters)

    return data_obj


def parse_filter_function(filter_str: str) -> Filters:
    """
    Parses a filter function string.

    Args:
        filter_str: A filter function string

    Returns:
        A Filters object with filters
    """
    filters = parse_filters(filter_str)
    return Filters({'filters': filters})


def parse_filters(input_str: str) -> List[Filter]:
    """
    Parses filter expressions from a string.

    Args:
        input_str: String containing filter expressions

    Returns:
        List of Filter objects
    """
    filter_pattern = r"filter\('([^']+)'\s*(?:,\s*'([^']+)')*\)"
    filters = []

    for match in re.finditer(filter_pattern, input_str):
        dimension = match.group(1)
        values_pattern = r"'([^']+)'"
        values = [m.group(1) for m in re.finditer(values_pattern, match.group(0))][1:]  # Skip the dimension

        filters.append(Filter(dimension, *values))

    return filters


def parse_param_string(params_string: str) -> List[str]:
    """
    Parses a parameter string into a list of parameters.

    Args:
        params_string: A string of parameters

    Returns:
        List of parameter strings
    """
    if not params_string:
        return []

    params = []
    current_param = ''
    bracket_depth = 0

    for char in params_string:
        if char == ',' and bracket_depth == 0:
            params.append(strip_quotes(current_param))
            current_param = ''
        else:
            current_param += char
            if char in ('(', '['):
                bracket_depth += 1
            elif char in (')', ']'):
                bracket_depth -= 1

    if current_param:
        if '=' in current_param:
            params.append(current_param.strip())
        else:
            params.append(strip_quotes(current_param))

    return params


def strip_quotes(string: str) -> str:
    """
    Removes surrounding quotes from a string.

    Args:
        string: Input string

    Returns:
        String with quotes removed if present
    """
    base_str = string.strip()
    if (base_str.startswith("'") and base_str.endswith("'")) or \
       (base_str.startswith('"') and base_str.endswith('"')):
        return base_str[1:-1]
    return base_str


def parse_query(signal_flow: str) -> Dict[str, List[str]]:
    """
    Parse a SignalFlow program to extract metrics

    Args:
        signal_flow: A SignalFlow program string

    Returns:
        Dictionary with metrics list
    """
    program = parse(signal_flow)
    return {'metrics': program.get_metrics()}
